class Solution:

    def maxScore(self, nums: List[int]) -> int:
        nums.sort()
        s = [0] * (len(nums) + 1)
        for k in range(1, len(nums) + 1):
            s[k] = s[k - 1] + nums[k - 1]
        ans = -1
        for k in range(3, len(nums) + 1):
            if s[k - 1] > nums[k - 1]:
                ans = max(ans, s[k])
        return ans
